"""Build the technical report from measured artifacts. Optional: pip install .[report]."""
from pathlib import Path
import argparse,json,html
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,Image,PageBreak,KeepTogether
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.utils import ImageReader
from reportlab.lib.pagesizes import letter


def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--root',type=Path,default=Path('.')); args=ap.parse_args(); root=args.root.resolve()
    r=json.loads((root/'artifacts/benchmark.json').read_text()); f=json.loads((root/'experiments/fullmap-v2/artifacts/followup.json').read_text())
    def row(d,name,p=.007,profile='uniform'):
        return next(z for z in r['rows'] if z['distance']==d and z['decoder']==name and z['noise']==p and z['profile']==profile)
    def pct(x):return f'{100*x:.3f}%'
    def total(rows,key,profile=None,d=None):
        a=[z for z in rows if z['decoder']==key and (profile is None or z['profile']==profile) and (d is None or z['distance']==d)]
        return sum(z['errors'] for z in a),sum(z['n'] for z in a)
    selected=[z for z in r['comparisons'] if z['decoder']==f'd{z["distance"]}_residual_s17' and z['baseline']=='correlated']
    gains=[z for z in selected if z['delta_ler']<0 and z['bonferroni_p']<.05]
    worse=[z for z in selected if z['delta_ler']>0 and z['bonferroni_p']<.05]
    primary_table=[['Distance','Standard','Correlated','FrameNet s17']]
    for d in (3,5,7):
        primary_table.append([f'd{d}',*[f'{row(d,k)["errors"]}/20,000 ({pct(row(d,k)["ler"])})' for k in ('standard','correlated',f'd{d}_residual_s17')]])
    mixture_table=[['Distance / profile','Standard failures','Correlated','FrameNet s17']]
    for d in (3,5,7):
        for profile in ('uniform','biased'):
            mixture_table.append([f'd{d} / {"uniform" if profile=="uniform" else "measurement-heavy"}',*[str(total(r['rows'],k,profile,d)[0]) for k in ('standard','correlated',f'd{d}_residual_s17')]])
    fit_table=[['Model','Parameters','Selected epoch','Fit + validation (s)']]
    for d in (3,5,7):
        ms=[m for m in r['models'] if m['distance']==d and m['variant']=='residual' and not m['single_noise']]
        fit_table.append([f'Compact d{d}, seeds 17/29/43','4,209',' / '.join(str(m['best_epoch']) for m in sorted(ms,key=lambda m:m['seed'])),f'{min(m["training_seconds"] for m in ms):.1f} - {max(m["training_seconds"] for m in ms):.1f}'])
    fit_table.append(['Full-map d3, seed 17',f'{f["parameters"]:,}',str(f['best_epoch']),f'{f["training_seconds"]:.1f}'])
    ablation_table=[['d3 model','Uniform failures','Shifted-profile failures']]
    for key,label in [('standard','Standard'),('correlated','Correlated'),('d3_residual_s17','Compact residual'),('d3_direct_s17','Direct logical head'),('d3_no_time_s17','No neural time order'),('d3_no_correlation_s17','No correlated context'),('d3_residual_s17_single','Single-p training')]:
        ablation_table.append([label,str(total(r['rows'],key,'uniform',3)[0]),str(total(r['rows'],key,'biased',3)[0])])
    follow_table=[['Fresh d3 test / model','Uniform failures','Shifted-profile failures']]
    for key,label in [('standard','Standard'),('correlated','Correlated'),('v1_residual','Compact residual'),('fullmap_v2','Full-map revision')]:
        follow_table.append([label,str(total(f['rows'],key,'uniform')[0]),str(total(f['rows'],key,'biased')[0])])
    latency_table=[['Distance / decoder','Batch 256 us/shot','Single median us','Observed p95 us']]
    for d in (3,5,7):
        for key,label in [('standard','standard'),('correlated','correlated'),(f'd{d}_residual_s17','FrameNet')]:
            z=row(d,key);latency_table.append([f'd{d} / {label}',f'{z["latency_us"]:.2f}',f'{z["single_shot_median_us"]:.1f}',f'{z["single_shot_p95_us"]:.1f}'])
    paired_table=[['d / profile / p','Neural wins','Neural losses','Delta LER, percentage points','Adjusted p']]
    for z in worse:
        paired_table.append([f'd{z["distance"]} / {z["profile"]} / {z["noise"]}',str(z['wins']),str(z['losses']),f'{100*z["delta_ler"]:+.3f}',f'{z["bonferroni_p"]:.2g}'])
    def mdtable(data):return '\n'.join(['| '+' | '.join(data[0])+' |','| '+' | '.join(['---']*len(data[0]))+' |']+['| '+' | '.join(a)+' |' for a in data[1:]])
    conclusion=(f'The compact neural hybrid is genuinely trained and produces verified syndrome-consistent logical-frame corrections. It does not establish an advantage over correlated matching: {len(gains)} of 42 primary setting comparisons favor it after correction for the 364 primary sweep comparisons. {len(worse)} settings significantly favor correlated matching. The larger full-map follow-up also fails to improve the fresh test mixture. Correlated PyMatching is the recommended decoder for these measured conditions.')
    methods=('Stim generated rotated surface-code X memories at distances 3, 5 and 7, with rounds equal to distance. Uniform noise sets after-Clifford depolarization, before-round data depolarization, before-measure flips and after-reset flips to the same nominal p. The shifted profile keeps gate p, uses idle p/4 and measurement/reset 2p. This is measurement-heavy channel imbalance, not Pauli-Z-biased noise, leakage or coherent noise. Both matching baselines receive each exact test circuit detector-error model, including decomposed correlation separators. Correlated matching is enabled in both graph construction and inference.')
    architecture=('FrameNet reads a two-channel space-time volume: detector bits and a detector-validity mask. Width-8 spatial 1x3x3 convolutions alternate with depthwise temporal 3x1x1 convolutions. A 2x2x2 pooled readout and 48-unit head also receive standard/correlated logical predictions, their disagreement, syndrome density and declared nominal p. The 4,209-parameter model learns true logical flip XOR standard prediction. Its residual bit toggles the standard logical frame. A shortest closed odd-logical graph cycle realizes that toggle without altering any detector parity. These are graphlike DEM recoveries, not unique physical Pauli trajectories.')
    training=('Each full compact model sees 60,000 retained training shots across p={0.003,0.007,0.012} for 10 epochs; validation uses 8,000 shots at each p. Seeds 17,29,43 vary initialization while sharing training data. AdamW uses learning rate 0.001, weight decay 0.0001, batch 512, float32 and four CPU threads. Class weighting is sqrt(negative/positive), capped at 8. Checkpoint and a grid-searched threshold are selected only on validation failures, with BCE breaking checkpoint ties. Seed17 is the declared primary model; all three initialization seeds are retained. Sigmoid values are uncalibrated class-weighted scores.')
    statistics=('Every primary setting has 20,000 independent held-out shots; all methods decode exactly the same retained vectors. LER is failures per full memory shot, not a fitted per-round rate. Marginal intervals are 95% Wilson. Paired wins/losses identify discordant errors. The exact two-sided paired binomial test is equivalent to exact McNemar on discordances. Global Bonferroni adjustment covers 364 primary comparisons. A conservative paired difference interval subtracts simultaneous Clopper-Pearson win/loss probability bounds, retaining nonzero uncertainty with zero disagreements. These intervals are marginal; simultaneous claims use adjusted p. Absence of significance does not establish equivalence.')
    ablation=('The direct head removes matching predictions and targets true logical flips. The time ablation averages neural inputs over time; matching context still uses the full history. The no-correlation control masks correlated predictions/disagreement. The single-p control uses the same total training/step budget at p=0.007 and mixed-p validation. Its seed is reused with a different sampling shape; exact prefixes differ, so it is not independent training randomness. Controls have one initialization, so small rankings are exploratory. The weak no-correlation and direct results show that much of the hybrid benefit over standard matching comes from access to correlated matching, not demonstrated new syndrome inference.')
    followup=('After observing the compact model mostly reproduce correlated matching, a targeted revision replaced 2x2x2 pooling with the full d3 feature map while preserving the encoder, 48-unit head, training shots, optimization steps and seed17. Parameter count rose to 25,713. It selected 971/24,000 validation failures versus compact seed17 968. A new high-bit random-stream namespace produced 280,000 independent d3 test shots across the same 14 settings. The fresh mixture is descriptive, not one physical operating point. The larger model does not improve it and is not promoted to the default demo. This adaptive follow-up is an engineering capacity test, not a preregistered scientific discovery.')
    timing=('All inference costs are measured on this Apple arm64 Mac using four PyTorch CPU threads, float32. Batch throughput is median warmed wall time of five batches of 256, divided by 256. Sequential single-shot median and empirical p95 use 32 shots. Hybrid costs include both matching calls, features, grid allocation/tensor conversion and neural inference. Sampling, disk, HTTP, graph construction and certificate construction are excluded. Final timings were refreshed without concurrent QubitGuard fits/tests; OS background load is uncontrolled. The 32-shot tail statistic is not a real-time bound. Fit times include validation but exclude prior data generation/baseline precomputation, and are observational under variable machine load, not a causal architecture speed ranking.')
    reproducibility=('The delivery retains exact circuits/DEMs, 61 primary NPZ datasets (1,152,000 stored shots including training/validation/control), 14 follow-up test datasets, 14 trained checkpoints, raw held-out predictions, checksums, exact dependency versions and source/config compatibility fingerprints. A full d3 seed17 retraining reproduced every learned tensor, threshold and selected epoch; its recorded checkpoint bytes also matched. Later cache/atomic-storage safeguards do not alter the numerical fitting rule. Initial artifact compatibility metadata was added transparently after full exact circuit, sample, baseline and feature replay. That audit is compatibility evidence, not a retroactive claim of immutable execution provenance. Exact cross-platform replay is not guaranteed.')
    limits=('No result here establishes a surface-code threshold, universal logical-operation coverage, neural distance transfer, quantum-hardware accuracy, leakage robustness, analog-readout decoding, streaming operation or real-time capability. Neural models support X memory only; the simulator also runs Z memories with explicit unavailable neural output. Unseen noise tests cover selected interpolation/extrapolation and channel imbalance only. The d7 seed29 shifted p=0.015 result is particularly unstable (6,338 failures versus correlated 5,703), despite similar validation performance. Stronger baselines, richer local representations and substantially larger rare-error training sets remain research directions, not proven remedies.')
    sources=('Primary foundations: Bausch et al., Nature 635, 834-840 (2024), doi:10.1038/s41586-024-08148-8; Chamberland et al., arXiv:2604.12841v1 (2026); Gidney, Quantum 5,497 (2021); Higgott and Gidney, Quantum 9,1600 (2025); Fowler, arXiv:1310.0863; Meinerz et al., arXiv:2101.07285v2; Gicev et al., arXiv:2506.16113; Lange et al., arXiv:2610.03869. See research-foundations.md and references.bib for links, prior-art boundaries and separate source/model licenses.')
    md=['# QubitGuard technical report','CPU-scale neural surface-code decoding study | 25 October 2026','## Result',conclusion,'## Primary comparison at p=0.007 (uniform)',mdtable(primary_table),'![Logical error rates](../figures/logical-error-uniform.png)','## Circuit and decoder methods',methods,architecture,training,mdtable(fit_table),'## Noise shift and paired evidence',mdtable(mixture_table),'Each mixture cell covers 140,000 shots over seven equally weighted noise settings; this is descriptive, not a hardware operating rate.',statistics,mdtable(paired_table),'![Shifted profile](../figures/logical-error-biased.png)','## Ablations',ablation,mdtable(ablation_table),'![Ablations](../figures/ablations.png)','## Readout revision and independent follow-up',followup,mdtable(follow_table),'## Cost',timing,mdtable(latency_table),'![CPU latency](../figures/cpu-latency.png)','## Reproducibility and engineering',reproducibility,'The full cached CLI run completed training-compatibility checks, held-out evaluation and plot export. Automated contracts cover both bases/all distances, independent graph parity and fault-trace reconstruction, hidden-truth invariance, seeded replay, source/data mutation, incomplete artifacts and concurrent API replay. See verification.json for final execution counts. The CI workflow is supplied but was not executed remotely.','## Interactive demonstration','The local playground exposes lattice/space-time views, detector-time stepping, real noise/distance/profile/basis controls, neural and classical recoveries, explicit logical failures, score provenance and exact benchmark tables. DEM-sampled mechanisms have one representative circuit explanation; they are not uniquely observed physical trajectories. A syndrome certificate and a logical outcome are deliberately separate.','## Limits and unresolved research',limits,'## Relation to NVIDIA and AlphaQubit','Published hardware timing and larger training experiments are contextual references, not reproduced numerical baselines. NVIDIA source and model-weight licenses are separate; gated NVIDIA weights were not downloaded or used. All QubitGuard checkpoints start from random initialization. Convolutional/hybrid decoding is prior art; the original contribution is this implementation, protocol, certificate pipeline, tested readout revision and measured negative/conditional results.','## References',sources]
    (root/'docs/technical-report.md').write_text('\n\n'.join(md)+'\n')
    styles=getSampleStyleSheet(); green=colors.HexColor('#284c3c'); gray=colors.HexColor('#536158')
    styles.add(ParagraphStyle(name='TitleQ',fontName='Helvetica-Bold',fontSize=31,leading=34,textColor=green,spaceAfter=12))
    styles.add(ParagraphStyle(name='SubQ',fontName='Helvetica',fontSize=10,leading=14,textColor=gray,spaceAfter=14))
    styles.add(ParagraphStyle(name='Hq',fontName='Helvetica-Bold',fontSize=17,leading=21,textColor=green,spaceAfter=11))
    styles.add(ParagraphStyle(name='BodyQ',fontName='Helvetica',fontSize=9.2,leading=13,spaceAfter=9,textColor=colors.HexColor('#23332a')))
    styles.add(ParagraphStyle(name='SmallQ',fontName='Helvetica',fontSize=8,leading=10.5,spaceAfter=7,textColor=gray))
    styles.add(ParagraphStyle(name='CellQ',fontName='Helvetica',fontSize=8,leading=10))
    story=[]
    def p(text,style='BodyQ'):story.append(Paragraph(html.escape(text),styles[style]))
    def heading(text):p(text,'Hq')
    def table(data,widths=None):
        cells=[[Paragraph(html.escape(str(x)),styles['CellQ']) for x in row] for row in data]
        t=Table(cells,colWidths=widths,repeatRows=1,hAlign='LEFT')
        t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e8eee4')),('TEXTCOLOR',(0,0),(-1,0),green),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f6f8f3')]),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6),('LINEBELOW',(0,0),(-1,0),.5,colors.HexColor('#b9c9b3'))]))
        story.append(t);story.append(Spacer(1,10))
    def figure(name,width=524):
        path=root/'figures'/name; iw,ih=ImageReader(str(path)).getSize();story.append(Image(str(path),width=width,height=width*ih/iw));story.append(Spacer(1,8))
    def page():story.append(PageBreak())
    p('QubitGuard','TitleQ');p('Neural error correction, measured against strong classical decoders.','SubQ');p('Technical report / v0.1.0 / 25 October 2026 / CPU experiments','SmallQ')
    p(conclusion);heading('Independent test results at p = 0.007')
    table(primary_table,[60,155,155,154]);p('Uniform circuit noise; 20,000 identical test shots per method and distance. These p values were seen during training, but test streams are independent.','SmallQ');figure('logical-error-uniform.png')
    p('Evidence: 14 trained checkpoints, 1,120,000 independent primary/follow-up test shots, saved data and raw predictions. No quantum hardware, paid API or external model weights were used.','SmallQ')
    page();heading('1 / What the model learns');p(methods);p(architecture);p(training);table(fit_table,[165,70,120,169]);figure('learning-curves.png');p('Fit times include validation. Initializations share data; they are not additional independent test samples.','SmallQ')
    page();heading('2 / Generalization and strong baselines');figure('logical-error-biased.png');table(mixture_table,[190,112,111,111]);p('Failures per 140,000-shot equal-weight noise mixture. Each row combines seven operating points, so it is not a hardware error rate.','SmallQ');p('The primary network beats standard matching in several regimes by using correlated matching context, but this does not establish new learned accuracy beyond correlated matching. At d5 p=0.015 both profiles significantly favor correlated matching after global adjustment. A similar validation score does not guarantee robust extrapolation.');table(paired_table,[140,65,65,170,84]);p('Wins: neural correct and correlated wrong. Losses: correlated correct and neural wrong. Positive delta favors correlated. Adjusted p uses all 364 primary paired comparisons.','SmallQ')
    page();heading('3 / Ablations and a rejected revision');p(ablation);table(ablation_table,[240,142,142]);p('Each cell counts failures across 140,000 independent test shots over seven noise settings. Every method sees the same shots.','SmallQ');figure('ablations.png');page();heading('4 / Readout revision on fresh data');p(followup);figure('paired-followup.png');table(follow_table,[240,142,142]);p('Follow-up mixture: 140,000 shots per profile, with a new independent stream. Full-map source, checkpoint, raw predictions and circuits are retained in experiments/fullmap-v2.','SmallQ')
    page();heading('5 / Full inference cost');figure('cpu-latency.png');table(latency_table,[160,125,120,119]);p(timing);p('The hybrid incurs both matching calls and neural overhead. Its measured cost and accuracy do not justify recommending it over correlated matching here. The larger readout is also retained as an unsuccessful engineering revision, rather than advertised as an improvement.');p(f'Environment: Python {r["environment"]["python"]}; PyTorch {r["environment"]["torch"]}; Stim {r["environment"]["stim"]}; PyMatching {r["environment"]["pymatching"]}; {r["environment"]["machine"]}.','SmallQ')
    page();heading('6 / Statistical and reproducibility protocol');p(statistics);p(reproducibility);p('The initial combined runner stopped before evaluation when a new guard rejected an obsolete ignored split-seed field loaded at process startup. The effective numerical training configuration was unchanged. Current strict CLI execution validates complete checkpoint pairs, relevant source/config/dependency signatures, dataset identities and retained circuit bytes before reuse. Incomplete artifacts are preserved and rejected. This history is recorded instead of implying an uninterrupted pristine run.');p('Automated tests reconstruct sampled DEM syndrome/logical truth and displayed correction parity without trusting returned certificate booleans. They also alter hidden truth to verify that inference cannot see it, compare an independent uncorrelated graph, exercise concurrent requests, and reject metadata/source/data mutations. Final test execution is recorded with the release artifacts.');p('Reproduce with: qubitguard verify; python scripts/replay_datasets.py --root .; qubitguard evaluate; qubitguard latency; qubitguard plot. New fitting experiments require a fresh root and the versioned configuration. See README for exact setup and model cards for supported conditions.');p('The local server has no external account/API dependency. Checkpoint integrity is checked before loading, shared mutable matching workspaces are serialized, unsupported neural scope is explicit, and a failed request preserves the prior valid shot.');
    page();heading('7 / Interactive system and research boundaries')
    shot=root/'figures'/'playground.png'
    if shot.exists():figure('playground.png');p('Current-source live playground, captured from the real local simulator. This shot is illustrative and is not benchmark evidence.','SmallQ')
    p('The playground shows a surface-code lattice and space-time detector history with stepping/playback, noise and distance controls, sampled error mechanisms, neural predictions, graph corrections and logical success/failure. It distinguishes a valid syndrome recovery from the correct logical class. Representative physical locations are explanatory possibilities, not a unique observed trajectory.');p(limits);p('Published NVIDIA GB300 timing and AlphaQubit hardware results are research context, not local reproductions. Their noise, training scale and hardware differ. NVIDIA source and model-weight licenses are separate; gated weights were not downloaded or redistributed. Newly initialized QubitGuard weights and original synthetic data use the project MIT license, while dependencies retain their licenses.','SmallQ');p(sources,'SmallQ');p('Original engineering: independently implemented simulation/data pipeline, compact logical-frame model, parity-certified recovery construction, strict paired protocol, readout-capacity follow-up, integrity checks and real simulator UI. No claim of a novel decoder family or groundbreaking superiority is made.','SmallQ')
    def footer(canvas,doc):
        canvas.setStrokeColor(colors.HexColor('#d9e2d4'));canvas.line(44,35,568,35);canvas.setFont('Helvetica',8);canvas.setFillColor(gray);canvas.drawString(44,23,'QubitGuard  |  Reproducible CPU-scale decoding study');canvas.drawRightString(568,23,str(doc.page))
    temp=root/'docs'/'technical-report.partial.pdf'
    doc=SimpleDocTemplate(str(temp),pagesize=letter,rightMargin=44,leftMargin=44,topMargin=42,bottomMargin=46,title='QubitGuard technical report',author='QubitGuard contributors')
    doc.build(story,onFirstPage=footer,onLaterPages=footer);temp.replace(root/'docs'/'technical-report.pdf')

if __name__=='__main__':main()
